import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Gifts and two-way trades","description":"","frontmatter":{"pageId":"players/gifts-trades","contentRevision":5},"headers":[],"relativePath":"en/players/gifts-trades.md","filePath":"en/players/gifts-trades.md"}'),n={name:"en/players/gifts-trades.md"};function o(i,e,d,l,c,f){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="gifts-and-two-way-trades" tabindex="-1">Gifts and two-way trades <a class="header-anchor" href="#gifts-and-two-way-trades" aria-label="Permalink to &quot;Gifts and two-way trades&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p><strong>Gift:</strong> select a player and the transfer contents. The recipient accepts, refuses or postpones the decision; refusal returns escrow to the sender. Unanswered gifts are declined after 7 days by default. Gift preferences and blocking affect new offers.</p><p><strong>Trade:</strong> open an offer and add items, pawns, silver and a note. The other party edits their side. Any edit invalidates earlier confirmations: both parties must confirm the same revision. Cancellation or expiry returns each contribution to its owner. Review the final contents before confirming.</p><p>After a disconnect, refresh trade state first. Do not send the same goods as a new gift while the first operation is unresolved.</p><h2 id="gift-flow" tabindex="-1">Gifts: dispatch, decision and return <a class="header-anchor" href="#gift-flow" aria-label="Permalink to &quot;Gifts: dispatch, decision and return {#gift-flow}&quot;">​</a></h2><p>Open <strong>Send</strong> at the comms console, choose the recipient, beacon-area goods/pawns and wallet silver. Recheck identity and contents: a pawn really leaves the colony. Wait for snapshot and response, then inspect operation state.</p><p>The recipient gets a letter: <strong>Accept</strong> permits delivery; <strong>Refuse</strong> returns goods and credits silver to the sender&#39;s wallet; <strong>Postpone</strong> keeps the decision pending. Mailbox offers the same actions. Unanswered gifts return after a week by default. Auto-accept gifts is a separate preference, not agreement to trades.</p><p>Blocking does not erase an already pending gift: it can still be refused. Do not send a second copy just because the recipient is offline.</p><h2 id="trade-flow" tabindex="-1">Two-way trades: what exactly do both parties confirm? <a class="header-anchor" href="#trade-flow" aria-label="Permalink to &quot;Two-way trades: what exactly do both parties confirm? {#trade-flow}&quot;">​</a></h2><ol><li>Use <strong>Trades → New trade</strong>, or <strong>Trade</strong> on a player with a settlement. Offline recipients are allowed.</li><li>Add goods/pawns, silver and a note. They enter server escrow, but nothing changes hands before both confirmations.</li><li>The partner changes their side. Review the complete current offer, not only the last message.</li><li><strong>Change my side</strong> <strong>adds</strong> goods. To replace them, request return of the previously offered goods; they arrive by mail. Silver and note are new totals.</li><li>An edit requires the other side to confirm the new revision. If the offer changed while the window was open, stale confirmation is not accepted.</li><li>Two confirmations of one revision settle into parcels. Either side may cancel, returning each escrow to its owner; expiry works similarly.</li></ol><p>Threat/debt prevents adding new outflow. Return, confirm and cancel remain completion paths. After a drop, refresh the same trade first.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The default trade lifetime is 7 days with at most 5 open trades. Closed trading and gift refusal are separate preferences. Accepting goods never requires sharing a password.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./economy">Wallet, mail and market</a></li><li><a href="./chat-pings">Chat, messages and pings</a></li><li><a href="./saves-recovery">Saves and recovery</a></li></ul>',17)])])}const g=t(n,[["render",o]]);export{p as __pageData,g as default};
